-- 023: innothule as it was from Classic to Velious (spawn points, groups and path grids from Quarm).
--
-- The dump has this zone in a later, revamped state. Generated by tools/npc_stats/gen_zone_from_quarm.py
-- (regenerate rather than edit): 225 spawn points, 21 spawn groups, 73 entries from the Quarm database,
-- ids + 1000000. NPCs are ours, matched by name; headings are Quarm's / 1.0198.
-- Level, HP, damage and AC taken from Quarm: Basher_Sklama: ours 46002 was level 34, Quarm has 50
-- Level, HP, damage and AC taken from Quarm: Basher_Smag: ours 46003 was level 35, Quarm has 50
-- Level, HP, damage and AC taken from Quarm: Basher_Trak: ours 46004 was level 40, Quarm has 50
-- Imported from Quarm (basic stats, loot table, faction list when we have none for the name): basher_oggrik as npc_types 46054
-- Imported from Quarm (basic stats, loot table, faction list when we have none for the name): a_froglok_guard as npc_types 46056
--
-- Our rows are kept in spawn2_before_era, spawngroup_before_era, spawnentry_before_era, grid_before_era and
-- grid_entries_before_era. To restore: delete the zone's rows with id >= 1000000 (spawn2, and spawngroup /
-- spawnentry by spawngroupID), delete its grid / grid_entries rows, and insert the *_before_era rows back.
-- Roamers: the boxes of Quarm's spawn groups become the zone's zone_roam_boxes (ours kept in zone_roam_boxes_before_era).
-- Idempotent.

CREATE TABLE IF NOT EXISTS spawn2_before_era LIKE spawn2;
CREATE TABLE IF NOT EXISTS spawngroup_before_era LIKE spawngroup;
CREATE TABLE IF NOT EXISTS spawnentry_before_era LIKE spawnentry;
CREATE TABLE IF NOT EXISTS grid_before_era LIKE grid;
CREATE TABLE IF NOT EXISTS grid_entries_before_era LIKE grid_entries;
CREATE TEMPORARY TABLE era_groups AS SELECT DISTINCT spawngroupID AS id FROM spawn2 WHERE zone = 'innothule' AND id < 1000000
  AND spawngroupID NOT IN (SELECT spawngroupID FROM spawn2 WHERE zone <> 'innothule');
DELETE FROM spawnentry WHERE spawngroupID IN (SELECT id FROM era_groups);
DELETE FROM spawngroup WHERE id IN (SELECT id FROM era_groups);
DELETE FROM spawn2 WHERE zone = 'innothule' AND id < 1000000;
DROP TEMPORARY TABLE era_groups;
DELETE FROM grid_entries WHERE zoneid = 46;
DELETE FROM grid WHERE zoneid = 46;



UPDATE npc_types SET npc_faction_id = (SELECT MIN(id) FROM npc_faction WHERE name = 'Basher_Oggrik') WHERE id = 46054 AND EXISTS (SELECT 1 FROM npc_faction WHERE name = 'Basher_Oggrik');
UPDATE npc_types_without SET npc_faction_id = (SELECT MIN(id) FROM npc_faction WHERE name = 'Basher_Oggrik') WHERE id = 46054 AND EXISTS (SELECT 1 FROM npc_faction WHERE name = 'Basher_Oggrik');
UPDATE npc_types SET npc_faction_id = (SELECT MIN(id) FROM npc_faction WHERE name = 'a_froglok_guard') WHERE id = 46056 AND EXISTS (SELECT 1 FROM npc_faction WHERE name = 'a_froglok_guard');
UPDATE npc_types_without SET npc_faction_id = (SELECT MIN(id) FROM npc_faction WHERE name = 'a_froglok_guard') WHERE id = 46056 AND EXISTS (SELECT 1 FROM npc_faction WHERE name = 'a_froglok_guard');

CREATE TABLE IF NOT EXISTS npc_types_before_era LIKE npc_types;
UPDATE npc_types SET level = 50, hp = 32000, mindmg = 61, maxdmg = 175, AC = 190 WHERE id = 46002;
UPDATE npc_types_without SET level = 50, hp = 32000, mindmg = 61, maxdmg = 175, AC = 190 WHERE id = 46002;
UPDATE npc_types SET level = 50, hp = 32000, mindmg = 61, maxdmg = 175, AC = 190 WHERE id = 46003;
UPDATE npc_types_without SET level = 50, hp = 32000, mindmg = 61, maxdmg = 175, AC = 190 WHERE id = 46003;
UPDATE npc_types SET level = 50, hp = 32000, mindmg = 61, maxdmg = 175, AC = 190 WHERE id = 46004;
UPDATE npc_types_without SET level = 50, hp = 32000, mindmg = 61, maxdmg = 175, AC = 190 WHERE id = 46004;



CREATE TABLE IF NOT EXISTS zone_roam_boxes_before_era LIKE zone_roam_boxes;
DELETE FROM zone_roam_boxes WHERE zone = 'innothule';



